CREATE OR REPLACE FUNCTION public.append_chat_group_mock_turn(p_group_id uuid, p_request_key uuid, p_content text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid:=auth.uid(); v_turn_id uuid; v_existing_content text; v_member_count integer;
  v_cost integer; v_silver integer; v_diamonds integer; v_balance_silver integer; v_balance_diamonds integer;
  v_pick integer; v_character_id uuid; v_scene_id uuid; v_character_name text; v_style text; v_scene_name text; v_character_snapshot jsonb;
BEGIN
  IF v_user_id IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
  IF NOT public.account_is_active() THEN RAISE EXCEPTION 'account_deletion_pending' USING ERRCODE='42501'; END IF;
  IF p_request_key IS NULL THEN RAISE EXCEPTION 'request_key_required' USING ERRCODE='22023'; END IF;
  IF p_content IS NULL OR char_length(btrim(p_content)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'invalid_message_content' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM public.chat_groups g WHERE g.id=p_group_id AND g.owner_id=v_user_id AND g.archived_at IS NULL AND g.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'group_not_found_or_not_accessible' USING ERRCODE='42501'; END IF;
  SELECT t.id,t.request_content INTO v_turn_id,v_existing_content FROM public.chat_group_turns t WHERE t.group_id=p_group_id AND t.request_key=p_request_key;
  IF FOUND THEN
    IF v_existing_content IS DISTINCT FROM btrim(p_content) THEN RAISE EXCEPTION 'idempotency_key_reused_with_different_content' USING ERRCODE='22023'; END IF;
    RETURN v_turn_id;
  END IF;
  SELECT count(*)::integer INTO v_member_count FROM public.chat_group_members m WHERE m.group_id=p_group_id;
  IF v_member_count NOT BETWEEN 1 AND 3 THEN RAISE EXCEPTION 'invalid_group_member_count' USING ERRCODE='23514'; END IF;
  v_cost:=v_member_count*3;
  PERFORM public.ensure_wallet_account();
  SELECT w.silver_coins,w.diamonds INTO v_balance_silver,v_balance_diamonds FROM public.wallet_accounts w WHERE w.user_id=v_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'wallet_not_initialized' USING ERRCODE='P0001'; END IF;
  IF COALESCE(v_balance_silver,0)+COALESCE(v_balance_diamonds,0)<v_cost THEN
    RAISE EXCEPTION 'group_insufficient_funds: required %, available %',v_cost,COALESCE(v_balance_silver,0)+COALESCE(v_balance_diamonds,0) USING ERRCODE='P0001';
  END IF;
  v_silver:=LEAST(v_balance_silver,v_cost); v_diamonds:=v_cost-v_silver;
  UPDATE public.wallet_accounts w SET silver_coins=w.silver_coins-v_silver,diamonds=w.diamonds-v_diamonds,updated_at=now() WHERE w.user_id=v_user_id;
  SELECT count(*)::integer % v_member_count INTO v_pick FROM public.chat_group_turns t WHERE t.group_id=p_group_id;
  INSERT INTO public.chat_group_turns(group_id,user_id,request_key,request_content) VALUES(p_group_id,v_user_id,p_request_key,btrim(p_content))
  ON CONFLICT(group_id,request_key) DO NOTHING RETURNING id INTO v_turn_id;
  IF v_turn_id IS NULL THEN RAISE EXCEPTION 'group_turn_request_conflict' USING ERRCODE='40001'; END IF;
  SELECT m.character_id,m.scene_id,m.character_snapshot,COALESCE(m.character_snapshot->>'name','角色'),
    COALESCE(m.character_snapshot->>'style',m.character_snapshot->>'intro','我會仔細留意目前的情況。'),COALESCE(s.name,'目前場景')
  INTO v_character_id,v_scene_id,v_character_snapshot,v_character_name,v_style,v_scene_name
  FROM public.chat_group_members m LEFT JOIN public.chat_group_scenes s ON s.id=m.scene_id AND s.group_id=m.group_id
  WHERE m.group_id=p_group_id ORDER BY m.position OFFSET v_pick LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'mock_director_no_valid_speaker' USING ERRCODE='23514'; END IF;
  INSERT INTO public.chat_group_messages(group_id,scene_id,turn_id,sequence_no,speaker_type,character_id,content)
  VALUES(p_group_id,v_scene_id,v_turn_id,0,'user',NULL,btrim(p_content));
  INSERT INTO public.chat_group_messages(group_id,scene_id,turn_id,sequence_no,speaker_type,character_id,content,speaker_snapshot)
  VALUES(p_group_id,v_scene_id,v_turn_id,1,'character',v_character_id,
    format('聽見你的話，%s 回應：「我明白了。%s 我們可以從「%s」開始，你接下來想怎麼做？」',v_character_name,v_style,v_scene_name),
    jsonb_build_object('id',COALESCE(v_character_snapshot->>'id',v_character_id::text),'name',v_character_name));
  INSERT INTO public.chat_group_turn_charges(group_id,group_turn_id,user_id,request_key,member_count,cost,silver_charged,diamonds_charged,status)
  VALUES(p_group_id,v_turn_id,v_user_id,p_request_key,v_member_count,v_cost,v_silver,v_diamonds,'settled');
  IF v_silver>0 THEN INSERT INTO public.wallet_transactions(user_id,currency_type,amount,biz_type,reference_id) VALUES(v_user_id,'silver_coins',-v_silver,'group_chat_turn_charge',v_turn_id::text); END IF;
  IF v_diamonds>0 THEN INSERT INTO public.wallet_transactions(user_id,currency_type,amount,biz_type,reference_id) VALUES(v_user_id,'diamonds',-v_diamonds,'group_chat_turn_charge',v_turn_id::text); END IF;
  UPDATE public.chat_groups SET updated_at=now() WHERE id=p_group_id;
  RETURN v_turn_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.archive_account_deletion_data(p_user_id uuid)
 RETURNS TABLE(batch_id uuid, target_user_id uuid, ai_source_rows bigint, ai_archived_rows bigint, wallet_source_rows bigint, wallet_archived_rows bigint, batch_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_requested_at timestamptz;
  v_scheduled_for timestamptz;
  v_batch_id uuid;
  v_ai_source bigint;
  v_ai_archived bigint;
  v_wallet_source bigint;
  v_wallet_archived bigint;
  v_existing_status text;
BEGIN
  IF p_user_id IS NULL THEN
    RAISE EXCEPTION '目標帳號不可為空';
  END IF;

  SELECT r.requested_at, r.scheduled_for
    INTO v_requested_at, v_scheduled_for
  FROM public.account_deletion_requests AS r
  WHERE r.user_id = p_user_id
    AND r.scheduled_for <= pg_catalog.statement_timestamp()
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '找不到此帳號已到期的刪除申請';
  END IF;

  -- Reuse a verified archive instead of creating duplicate batches on retries.
  SELECT b.id, b.status
    INTO v_batch_id, v_existing_status
  FROM public.account_deletion_archive_batches AS b
  WHERE b.target_user_id = p_user_id
    AND b.requested_at = v_requested_at
    AND b.scheduled_for = v_scheduled_for
    AND b.status IN ('archived', 'deleting', 'completed')
  ORDER BY b.created_at DESC
  LIMIT 1
  FOR UPDATE;

  IF FOUND THEN
    SELECT pg_catalog.count(*) INTO v_ai_archived
    FROM public.account_deletion_archive_items AS i
    WHERE i.batch_id = v_batch_id
      AND i.source_table = 'ai_generation_records';

    SELECT pg_catalog.count(*) INTO v_wallet_archived
    FROM public.account_deletion_archive_items AS i
    WHERE i.batch_id = v_batch_id
      AND i.source_table = 'wallet_transactions';

    SELECT pg_catalog.count(*) INTO v_ai_source
    FROM public.ai_generation_records AS a
    WHERE a.user_id = p_user_id;

    SELECT pg_catalog.count(*) INTO v_wallet_source
    FROM public.wallet_transactions AS w
    WHERE w.user_id = p_user_id;

    RETURN QUERY SELECT v_batch_id, p_user_id, v_ai_source, v_ai_archived,
      v_wallet_source, v_wallet_archived, v_existing_status;
    RETURN;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.account_deletion_archive_batches AS b
    WHERE b.target_user_id = p_user_id
      AND b.status IN ('pending', 'archiving', 'deleting')
  ) THEN
    RAISE EXCEPTION '此帳號已有正在處理的封存／刪除批次';
  END IF;

  INSERT INTO public.account_deletion_archive_batches (
    target_user_id, status, requested_at, scheduled_for, started_at,
    attempt_count, last_error
  )
  VALUES (
    p_user_id, 'archiving', v_requested_at, v_scheduled_for,
    pg_catalog.statement_timestamp(), 1, NULL
  )
  RETURNING id INTO v_batch_id;

  SELECT pg_catalog.count(*) INTO v_ai_source
  FROM public.ai_generation_records AS a
  WHERE a.user_id = p_user_id;

  SELECT pg_catalog.count(*) INTO v_wallet_source
  FROM public.wallet_transactions AS w
  WHERE w.user_id = p_user_id;

  INSERT INTO public.account_deletion_archive_items AS dst (
    batch_id, source_table, source_record_id, payload
  )
  SELECT v_batch_id, 'ai_generation_records', a.id::text, pg_catalog.to_jsonb(a)
  FROM public.ai_generation_records AS a
  WHERE a.user_id = p_user_id
  ON CONFLICT ON CONSTRAINT account_deletion_archive_item_batch_id_source_table_source__key
  DO NOTHING;

  INSERT INTO public.account_deletion_archive_items AS dst (
    batch_id, source_table, source_record_id, payload
  )
  SELECT v_batch_id, 'wallet_transactions', w.id::text, pg_catalog.to_jsonb(w)
  FROM public.wallet_transactions AS w
  WHERE w.user_id = p_user_id
  ON CONFLICT ON CONSTRAINT account_deletion_archive_item_batch_id_source_table_source__key
  DO NOTHING;

  SELECT pg_catalog.count(*) INTO v_ai_archived
  FROM public.account_deletion_archive_items AS i
  WHERE i.batch_id = v_batch_id AND i.source_table = 'ai_generation_records';

  SELECT pg_catalog.count(*) INTO v_wallet_archived
  FROM public.account_deletion_archive_items AS i
  WHERE i.batch_id = v_batch_id AND i.source_table = 'wallet_transactions';

  IF v_ai_source <> v_ai_archived OR v_wallet_source <> v_wallet_archived THEN
    RAISE EXCEPTION '封存筆數不一致，已取消本次交易';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.ai_generation_records AS a
    LEFT JOIN public.account_deletion_archive_items AS i
      ON i.batch_id = v_batch_id
     AND i.source_table = 'ai_generation_records'
     AND i.source_record_id = a.id::text
    WHERE a.user_id = p_user_id
      AND (i.id IS NULL OR i.payload IS DISTINCT FROM pg_catalog.to_jsonb(a))
  ) THEN
    RAISE EXCEPTION 'AI 原始生成紀錄內容核對失敗';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.wallet_transactions AS w
    LEFT JOIN public.account_deletion_archive_items AS i
      ON i.batch_id = v_batch_id
     AND i.source_table = 'wallet_transactions'
     AND i.source_record_id = w.id::text
    WHERE w.user_id = p_user_id
      AND (i.id IS NULL OR i.payload IS DISTINCT FROM pg_catalog.to_jsonb(w))
  ) THEN
    RAISE EXCEPTION '錢包交易紀錄內容核對失敗';
  END IF;

  UPDATE public.account_deletion_archive_batches AS b
  SET status = 'archived',
      updated_at = pg_catalog.statement_timestamp(),
      last_error = NULL
  WHERE b.id = v_batch_id;

  RETURN QUERY SELECT v_batch_id, p_user_id, v_ai_source, v_ai_archived,
    v_wallet_source, v_wallet_archived, 'archived'::text;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_account_deletion()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_requested_at timestamptz;
  v_scheduled_for timestamptz;
  v_now timestamptz := pg_catalog.statement_timestamp();
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION '請先登入';
  END IF;

  -- Lock the request so recovery cannot race with a worker starting the same request.
  SELECT r.requested_at, r.scheduled_for
    INTO v_requested_at, v_scheduled_for
  FROM public.account_deletion_requests AS r
  WHERE r.user_id = v_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '找不到待處理的刪除申請';
  END IF;

  -- Before the deadline, normal cancellation is allowed.
  -- After the deadline, recovery is allowed only if no archive/deletion batch
  -- has been created for this exact request. Once processing has started,
  -- manual recovery is blocked to avoid racing with deletion.
  IF v_scheduled_for <= v_now AND EXISTS (
    SELECT 1
    FROM public.account_deletion_archive_batches AS b
    WHERE b.target_user_id = v_user_id
      AND b.requested_at = v_requested_at
      AND b.scheduled_for = v_scheduled_for
  ) THEN
    RAISE EXCEPTION '刪除處理已開始，無法透過此功能復原；請交由管理程序檢查';
  END IF;

  DELETE FROM public.account_deletion_requests AS r
  WHERE r.user_id = v_user_id
    AND r.requested_at = v_requested_at
    AND r.scheduled_for = v_scheduled_for;

  IF NOT FOUND THEN
    RAISE EXCEPTION '刪除申請狀態已變更，請重新查詢帳號狀態';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_daily_checkin()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_reward integer;
  v_enabled boolean;
  v_balance integer;
  v_last_day smallint;
  v_cycle_day smallint := 1;
  v_existing_day smallint;
begin
  if v_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if exists (select 1 from public.account_deletion_requests adr where adr.user_id = v_user_id) then
    raise exception 'account deletion pending' using errcode = '42501';
  end if;

  select wa.silver_coins
    into v_balance
  from public.wallet_accounts wa
  where wa.user_id = v_user_id
  for update;

  if not found then
    raise exception 'wallet account not found' using errcode = 'P0002';
  end if;

  select s.reward_silver, s.enabled
    into v_reward, v_enabled
  from public.daily_checkin_settings s
  where s.id = 1;

  if not found then
    v_reward := 10;
    v_enabled := true;
  end if;

  if not v_enabled then
    raise exception 'daily check-in is disabled' using errcode = '42501';
  end if;

  select c.cycle_day into v_existing_day
  from public.daily_checkins c
  where c.user_id = v_user_id and c.checkin_date = v_today;

  if found then
    return jsonb_build_object(
      'granted', false,
      'claimed_today', true,
      'reward', v_reward,
      'cycle_day', v_existing_day,
      'silver_balance', v_balance,
      'today', v_today
    );
  end if;

  select c.cycle_day into v_last_day
  from public.daily_checkins c
  where c.user_id = v_user_id
  order by c.checkin_date desc
  limit 1;

  if v_last_day is not null then
    v_cycle_day := (v_last_day % 7) + 1;
  end if;

  insert into public.daily_checkins (user_id, checkin_date, cycle_day, reward_silver)
  values (v_user_id, v_today, v_cycle_day, v_reward);

  update public.wallet_accounts
    set silver_coins = silver_coins + v_reward,
        updated_at = now()
  where user_id = v_user_id
  returning silver_coins into v_balance;

  insert into public.wallet_transactions
    (user_id, currency_type, amount, biz_type, reference_id)
  values
    (v_user_id, 'silver_coins', v_reward, 'daily_checkin', 'daily_checkin:' || v_today::text);

  return jsonb_build_object(
    'granted', true,
    'claimed_today', true,
    'reward', v_reward,
    'cycle_day', v_cycle_day,
    'silver_balance', v_balance,
    'today', v_today
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_chat_group(p_name text, p_world_background text, p_scene_mode text, p_scenes jsonb, p_members jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_group_id uuid;
  v_scene jsonb;
  v_member jsonb;
  v_character_id uuid;
  v_scene_id uuid;
  v_position smallint := 0;
  v_member_count integer;
  v_character public.characters%ROWTYPE;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
  END IF;
  IF EXISTS (SELECT 1 FROM public.account_deletion_requests r WHERE r.user_id = v_user_id) THEN
    RAISE EXCEPTION 'account_deletion_pending' USING ERRCODE = '42501';
  END IF;
  IF p_name IS NULL OR char_length(btrim(p_name)) NOT BETWEEN 1 AND 80 THEN
    RAISE EXCEPTION 'invalid_group_name' USING ERRCODE = '22023';
  END IF;
  IF p_world_background IS NULL OR char_length(p_world_background) > 10000 THEN
    RAISE EXCEPTION 'invalid_world_background' USING ERRCODE = '22023';
  END IF;
  IF p_scene_mode IS DISTINCT FROM 'shared' THEN
    RAISE EXCEPTION 'group_scene_mode_must_be_shared' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_members) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'members_must_be_array' USING ERRCODE = '22023';
  END IF;
  v_member_count := jsonb_array_length(p_members);
  IF v_member_count NOT BETWEEN 1 AND 3 THEN
    RAISE EXCEPTION 'group_requires_one_to_three_characters' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(p_scenes) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid_scenes' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_scenes) <> 1 THEN
    RAISE EXCEPTION 'shared_mode_requires_one_scene' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.chat_groups(owner_id, name, world_background, scene_mode)
  VALUES (v_user_id, btrim(p_name), p_world_background, 'shared')
  RETURNING id INTO v_group_id;

  v_scene := p_scenes->0;
  IF jsonb_typeof(v_scene) IS DISTINCT FROM 'object'
     OR jsonb_typeof(v_scene->'name') IS DISTINCT FROM 'string'
     OR (v_scene ? 'description' AND jsonb_typeof(v_scene->'description') IS DISTINCT FROM 'string')
     OR char_length(btrim(COALESCE(v_scene->>'name',''))) NOT BETWEEN 1 AND 80
     OR char_length(COALESCE(v_scene->>'description','')) > 5000 THEN
    RAISE EXCEPTION 'invalid_scene_payload' USING ERRCODE = '22023';
  END IF;
  INSERT INTO public.chat_group_scenes(group_id, name, description, position)
  VALUES (v_group_id, btrim(v_scene->>'name'), COALESCE(v_scene->>'description',''), 1)
  RETURNING id INTO v_scene_id;

  FOR v_member IN SELECT value FROM jsonb_array_elements(p_members)
  LOOP
    v_position := v_position + 1;
    IF jsonb_typeof(v_member) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_member->'character_id') IS DISTINCT FROM 'string'
       OR NULLIF(v_member->>'character_id', '') IS NULL THEN
      RAISE EXCEPTION 'invalid_member_payload' USING ERRCODE = '22023';
    END IF;
    BEGIN
      v_character_id := (v_member->>'character_id')::uuid;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'invalid_character_id' USING ERRCODE = '22023';
    END;

    -- A character can join a group whenever it is public and not taken down.
    -- review_status is intentionally not an access gate: there is no pre-publication review workflow.
    SELECT c.* INTO v_character
    FROM public.characters c
    WHERE c.id = v_character_id
      AND c.deleted_at IS NULL
      AND c.visibility = 'public'
    FOR SHARE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'character_not_public_or_unavailable' USING ERRCODE = '42501';
    END IF;

    IF EXISTS (
      SELECT 1 FROM public.chat_group_members m
      WHERE m.group_id = v_group_id AND m.character_id = v_character_id
    ) THEN
      RAISE EXCEPTION 'duplicate_character' USING ERRCODE = '22023';
    END IF;
    INSERT INTO public.chat_group_members(group_id, character_id, position, scene_id, character_snapshot)
    VALUES (
      v_group_id, v_character_id, v_position, v_scene_id,
      jsonb_build_object(
        'id', v_character.id, 'name', v_character.name, 'gender', v_character.gender,
        'age', v_character.age, 'intro', v_character.intro,
        'opening', COALESCE((
          SELECT cs.opening_message FROM public.character_stories cs
          WHERE cs.character_id = v_character.id
            AND cs.visibility = 'public'
          ORDER BY cs.created_at ASC LIMIT 1
        ), ''),
        'race', v_character.race, 'style', v_character.style, 'tags', v_character.tags
      )
    );
  END LOOP;
  RETURN v_group_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_story_session_with_relationship(p_session_id uuid, p_user_id uuid, p_character_id uuid, p_character_name text, p_character_snapshot jsonb, p_origin_mode text, p_source_encounter_session_id uuid, p_affinity integer, p_relationship_stage text, p_imported_memories jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_session jsonb;
BEGIN
  IF p_origin_mode NOT IN ('fresh_story', 'encounter_snapshot') THEN
    RAISE EXCEPTION 'Invalid Story relationship origin' USING ERRCODE = '22023';
  END IF;
  IF p_affinity IS NULL OR p_affinity < -100 OR p_affinity > 100 THEN
    RAISE EXCEPTION 'Story affinity is outside the allowed range' USING ERRCODE = '22023';
  END IF;
  IF jsonb_typeof(COALESCE(p_imported_memories, '[]'::jsonb)) <> 'array' THEN
    RAISE EXCEPTION 'Imported memories must be an array' USING ERRCODE = '22023';
  END IF;
  IF pg_column_size(COALESCE(p_imported_memories, '[]'::jsonb)) > 20000 THEN
    RAISE EXCEPTION 'Imported memories are too large' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.chat_sessions (
    id, user_id, character_id, character_name, status,
    character_snapshot, session_data, chat_mode
  ) VALUES (
    p_session_id, p_user_id, p_character_id, p_character_name, 'active',
    COALESCE(p_character_snapshot, '{}'::jsonb), '{}'::jsonb, 'story'
  );

  INSERT INTO public.story_relationship_states (
    session_id, user_id, character_id, origin_mode,
    affinity, relationship_stage, source_encounter_session_id,
    origin_affinity, origin_relationship_stage, imported_memories, snapshot_at
  ) VALUES (
    p_session_id, p_user_id, p_character_id, p_origin_mode,
    p_affinity, p_relationship_stage, p_source_encounter_session_id,
    p_affinity, p_relationship_stage, COALESCE(p_imported_memories, '[]'::jsonb),
    CASE WHEN p_origin_mode = 'encounter_snapshot' THEN now() ELSE NULL END
  );

  SELECT jsonb_build_object(
    'id', s.id,
    'user_id', s.user_id,
    'character_id', s.character_id,
    'character_name', s.character_name,
    'status', s.status,
    'character_snapshot', s.character_snapshot,
    'chat_mode', s.chat_mode,
    'created_at', s.created_at,
    'updated_at', s.updated_at
  ) INTO v_session
  FROM public.chat_sessions AS s
  WHERE s.id = p_session_id;

  RETURN v_session;
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_chat_group_with_related_data(p_group_id uuid)
 RETURNS TABLE(storage_path text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_owner_id uuid;
  v_deleted_at timestamptz;
  v_job_id uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.account_deletion_requests r
    WHERE r.user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'account_deletion_pending' USING ERRCODE = '42501';
  END IF;

  SELECT g.owner_id, g.deleted_at
    INTO v_owner_id, v_deleted_at
  FROM public.chat_groups g
  WHERE g.id = p_group_id
  FOR UPDATE;

  IF NOT FOUND OR v_owner_id IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'group_not_found_or_not_owned' USING ERRCODE = '42501';
  END IF;

  v_deleted_at := COALESCE(v_deleted_at, pg_catalog.statement_timestamp());

  INSERT INTO public.chat_deletion_jobs (
    resource_type, resource_id, owner_id, deleted_at, purge_after, status
  )
  VALUES (
    'group', p_group_id, v_user_id, v_deleted_at,
    v_deleted_at + interval '30 days', 'queued'
  )
  ON CONFLICT (resource_type, resource_id) DO NOTHING;

  SELECT j.id
    INTO v_job_id
  FROM public.chat_deletion_jobs j
  WHERE j.resource_type = 'group'
    AND j.resource_id = p_group_id
    AND j.owner_id = v_user_id
    AND j.deleted_at = v_deleted_at
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'chat_deletion_job_conflict' USING ERRCODE = '40001';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.chat_memory_photos p
    WHERE p.group_id = p_group_id
      AND p.chat_type = 'group'
      AND p.owner_id = v_user_id
      AND left(p.storage_path, char_length(v_user_id::text) + 1) <> v_user_id::text || '/'
  ) THEN
    RAISE EXCEPTION 'chat_storage_path_owner_mismatch' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.chat_storage_deletion_jobs (
    deletion_job_id, bucket_id, object_path, resource_type, resource_id, owner_id
  )
  SELECT
    v_job_id, 'personax-memory-photos', p.storage_path,
    'group', p_group_id, v_user_id
  FROM public.chat_memory_photos p
  WHERE p.group_id = p_group_id
    AND p.chat_type = 'group'
    AND p.owner_id = v_user_id
  ON CONFLICT (bucket_id, object_path) DO NOTHING;

  IF EXISTS (
    SELECT 1
    FROM public.chat_storage_deletion_jobs sj
    JOIN public.chat_memory_photos p ON p.storage_path = sj.object_path
    WHERE p.group_id = p_group_id
      AND p.chat_type = 'group'
      AND p.owner_id = v_user_id
      AND (sj.owner_id <> v_user_id OR sj.deletion_job_id <> v_job_id)
  ) THEN
    RAISE EXCEPTION 'chat_storage_deletion_job_conflict' USING ERRCODE = '40001';
  END IF;

  UPDATE public.chat_groups g
  SET deleted_at = COALESCE(g.deleted_at, v_deleted_at),
      updated_at = pg_catalog.statement_timestamp()
  WHERE g.id = p_group_id
    AND g.owner_id = v_user_id;

  RETURN QUERY SELECT NULL::text WHERE false;
END;
$function$

