CREATE OR REPLACE FUNCTION public.enqueue_due_encounter_evaluations(p_limit integer DEFAULT 50)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l public.encounter_session_lifecycle%ROWTYPE; v_enqueued integer:=0; v_rows integer:=0; v_limit integer:=LEAST(GREATEST(COALESCE(p_limit,50),1),100); v_session_id uuid;
BEGIN
  FOR v_session_id IN
    SELECT s.id FROM public.chat_sessions s JOIN public.encounter_session_lifecycle lifecycle ON lifecycle.session_id=s.id
    WHERE s.deleted_at IS NULL AND lifecycle.status IN ('active','paused','ready_to_settle') AND lifecycle.character_id IS NOT NULL AND lifecycle.scheduled_end_at<=clock_timestamp()
    ORDER BY lifecycle.scheduled_end_at,lifecycle.session_id FOR UPDATE OF s SKIP LOCKED LIMIT v_limit
  LOOP
    SELECT lifecycle.* INTO l FROM public.encounter_session_lifecycle lifecycle WHERE lifecycle.session_id=v_session_id FOR UPDATE;
    IF NOT FOUND THEN CONTINUE; END IF;
    IF EXISTS(SELECT 1 FROM public.chat_turn_charges charge WHERE charge.session_id=l.session_id AND charge.status IN ('created','reserved','needs_reconciliation')) THEN CONTINUE; END IF;
    IF (SELECT count(*) FROM public.encounter_session_turns turn WHERE turn.session_id=l.session_id)<>l.turn_count THEN CONTINUE; END IF;
    UPDATE public.encounter_session_lifecycle SET status='ready_to_settle',updated_at=clock_timestamp() WHERE session_id=l.session_id AND status IN ('active','paused','ready_to_settle');
    INSERT INTO public.encounter_session_evaluation_jobs(session_id,user_id,character_id,status) VALUES(l.session_id,l.user_id,l.character_id,'pending')
    ON CONFLICT(session_id) DO UPDATE SET status='pending',claimed_at=NULL,completed_at=NULL,last_error=NULL,updated_at=clock_timestamp()
    WHERE public.encounter_session_evaluation_jobs.status='failed' AND public.encounter_session_evaluation_jobs.attempt_count<5 AND public.encounter_session_evaluation_jobs.updated_at<=clock_timestamp()-interval '5 minutes';
    GET DIAGNOSTICS v_rows=ROW_COUNT; v_enqueued:=v_enqueued+v_rows;
  END LOOP;
  RETURN v_enqueued;
END;
$function$

CREATE OR REPLACE FUNCTION public.ensure_wallet_account()
 RETURNS TABLE(diamonds integer, silver_coins integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_rows integer;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception '請先登入';
  end if;
  if not public.account_is_active() then
    raise exception '帳號正在等待刪除，請先取消刪除申請';
  end if;

  insert into public.wallet_accounts (
    user_id, diamonds, silver_coins, updated_at
  )
  values (v_user_id, 0, 100, now())
  on conflict (user_id) do nothing;
  get diagnostics v_rows = row_count;
  if v_rows > 0 then
    insert into public.wallet_transactions (
      user_id, currency_type, amount, biz_type, reference_id
    )
    values (
      v_user_id, 'silver_coins', 100, 'signup_bonus', 'initial_wallet_grant'
    );
  end if;

  return query
  select wa.diamonds, wa.silver_coins
  from public.wallet_accounts as wa
  where wa.user_id = v_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_encounter_evaluation_job(p_session_id uuid, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_updated integer;
BEGIN
  IF p_session_id IS NULL THEN
    RAISE EXCEPTION 'Invalid evaluation job session' USING ERRCODE='22023';
  END IF;

  UPDATE public.encounter_session_evaluation_jobs
  SET status='failed',claimed_at=NULL,last_error=left(COALESCE(p_error,'evaluation_failed'),500),
      updated_at=clock_timestamp()
  WHERE session_id=p_session_id AND status='processing';

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RETURN v_updated=1;
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_account_deletion(p_batch_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_status text;
  v_user_id uuid;
BEGIN
  IF p_batch_id IS NULL THEN
    RAISE EXCEPTION '封存批次不可為空';
  END IF;

  SELECT b.status, b.target_user_id
    INTO v_status, v_user_id
  FROM public.account_deletion_archive_batches AS b
  WHERE b.id = p_batch_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION '找不到封存批次';
  END IF;

  IF v_status = 'completed' THEN
    RETURN true;
  END IF;

  IF v_status <> 'deleting' THEN
    RAISE EXCEPTION '批次尚未進入 deleting 狀態';
  END IF;

  IF EXISTS (SELECT 1 FROM auth.users AS u WHERE u.id = v_user_id) THEN
    RAISE EXCEPTION 'Auth 帳號仍存在，不能標記刪除完成';
  END IF;

  UPDATE public.account_deletion_archive_batches
  SET status = 'completed',
      completed_at = pg_catalog.statement_timestamp(),
      updated_at = pg_catalog.statement_timestamp(),
      last_error = NULL
  WHERE id = p_batch_id;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_daily_checkin_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_today date := (now() at time zone 'Asia/Taipei')::date;
  v_reward integer;
  v_enabled boolean;
  v_today_day smallint;
  v_last_day smallint;
  v_claimed_today boolean := false;
  v_next_day smallint := 1;
  v_last_date date;
begin
  if v_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if exists (select 1 from public.account_deletion_requests adr where adr.user_id = v_user_id) then
    raise exception 'account deletion pending' using errcode = '42501';
  end if;

  select s.reward_silver, s.enabled
    into v_reward, v_enabled
  from public.daily_checkin_settings s
  where s.id = 1;

  if not found then
    v_reward := 10;
    v_enabled := true;
  end if;

  select c.cycle_day into v_today_day
  from public.daily_checkins c
  where c.user_id = v_user_id and c.checkin_date = v_today;

  v_claimed_today := found;

  select c.cycle_day, c.checkin_date
    into v_last_day, v_last_date
  from public.daily_checkins c
  where c.user_id = v_user_id
  order by c.checkin_date desc
  limit 1;

  if v_claimed_today then
    v_next_day := v_today_day;
  elsif v_last_day is not null then
    v_next_day := (v_last_day % 7) + 1;
  end if;

  return jsonb_build_object(
    'reward', v_reward,
    'enabled', v_enabled,
    'claimed_today', v_claimed_today,
    'cycle_day', v_next_day,
    'last_checkin_date', v_last_date,
    'today', v_today
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_chat_turn_assistant_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_charge public.chat_turn_charges%rowtype;
BEGIN
  PERFORM 1 FROM public.chat_sessions s WHERE s.id=NEW.session_id AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'chat_session_not_found_or_deleted'; END IF;
  SELECT c.* INTO v_charge FROM public.chat_turn_charges c WHERE c.expected_assistant_message_id=NEW.id FOR UPDATE;
  IF FOUND THEN
    IF NEW.role IS DISTINCT FROM 'assistant' THEN RAISE EXCEPTION 'expected_assistant_message_id_role_conflict'; END IF;
    IF NEW.session_id IS DISTINCT FROM v_charge.session_id THEN RAISE EXCEPTION 'expected_assistant_message_session_conflict'; END IF;
    IF v_charge.status IS DISTINCT FROM 'reserved' AND v_charge.status IS DISTINCT FROM 'needs_reconciliation' THEN RAISE EXCEPTION 'assistant_insert_requires_unresolved_charge'; END IF;
    IF char_length(btrim(coalesce(NEW.content,'')))=0 THEN RAISE EXCEPTION 'assistant_reply_content_required'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.role='assistant' THEN RAISE EXCEPTION 'assistant_reply_requires_chat_turn'; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_chat_turn_assistant_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_locked_charge public.chat_turn_charges%rowtype; v_old_charge public.chat_turn_charges%rowtype;
  v_new_charge public.chat_turn_charges%rowtype; v_has_old_charge boolean:=false;
  v_has_new_charge boolean:=false; v_content_changed boolean; v_deleted_changed boolean;
BEGIN
  IF auth.role()='service_role' AND current_setting('app.chat_purge_worker',true)='on' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.session_id IS DISTINCT FROM OLD.session_id OR NEW.role IS DISTINCT FROM OLD.role THEN
      RAISE EXCEPTION 'chat_purge_worker_identity_change_forbidden';
    END IF;
    RETURN NEW;
  END IF;
  PERFORM 1 FROM public.chat_sessions s WHERE s.id=OLD.session_id AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'chat_session_not_found_or_deleted'; END IF;
  IF NEW.role IS DISTINCT FROM OLD.role THEN RAISE EXCEPTION 'chat_message_role_is_immutable'; END IF;
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.session_id IS DISTINCT FROM OLD.session_id THEN
    IF OLD.role='assistant' THEN RAISE EXCEPTION 'assistant_message_identity_is_immutable';
    ELSE RAISE EXCEPTION 'user_message_identity_is_immutable'; END IF;
  END IF;
  IF OLD.role<>'assistant' THEN RETURN NEW; END IF;
  v_content_changed:=NEW.content IS DISTINCT FROM OLD.content;
  v_deleted_changed:=NEW.deleted_at IS DISTINCT FROM OLD.deleted_at;
  FOR v_locked_charge IN SELECT c.* FROM public.chat_turn_charges c
    WHERE c.expected_assistant_message_id=OLD.id OR c.expected_assistant_message_id=NEW.id
    ORDER BY c.expected_assistant_message_id FOR UPDATE
  LOOP
    IF v_locked_charge.expected_assistant_message_id=OLD.id THEN v_old_charge:=v_locked_charge;v_has_old_charge:=true;END IF;
    IF v_locked_charge.expected_assistant_message_id=NEW.id THEN v_new_charge:=v_locked_charge;v_has_new_charge:=true;END IF;
  END LOOP;
  IF v_has_old_charge AND v_has_new_charge AND v_old_charge.turn_id IS DISTINCT FROM v_new_charge.turn_id THEN RAISE EXCEPTION 'assistant_message_turn_id_conflict';END IF;
  IF v_has_old_charge AND OLD.id IS DISTINCT FROM v_old_charge.expected_assistant_message_id THEN RAISE EXCEPTION 'assistant_message_turn_id_conflict';END IF;
  IF v_deleted_changed THEN
    IF v_content_changed THEN RAISE EXCEPTION 'assistant_reply_edit_and_delete_must_be_separate';END IF;
    IF v_has_old_charge AND v_old_charge.status IS DISTINCT FROM 'settled' THEN RAISE EXCEPTION 'chat_turn_reply_delete_requires_settled_charge';END IF;
    RETURN NEW;
  END IF;
  IF v_content_changed AND v_has_old_charge AND v_old_charge.status IS DISTINCT FROM 'settled' THEN RAISE EXCEPTION 'assistant_reply_edit_requires_settled_charge';END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_pending_account_character_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_owner_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_owner_id := OLD.author_id;
  ELSE
    v_owner_id := NEW.author_id;
  END IF;

  IF auth.uid() IS NOT NULL
     AND auth.uid() = v_owner_id
     AND EXISTS (
       SELECT 1 FROM public.account_deletion_requests AS r
       WHERE r.user_id = v_owner_id
     ) THEN
    RAISE EXCEPTION 'account_deletion_pending' USING ERRCODE = '42501';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_pending_account_group_activity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid;
BEGIN
  IF TG_TABLE_NAME = 'chat_groups' THEN
    v_user_id := NEW.owner_id;
  ELSIF TG_TABLE_NAME = 'chat_group_turns' THEN
    v_user_id := NEW.user_id;
  ELSE
    RAISE EXCEPTION 'unsupported_group_activity_table';
  END IF;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'group_activity_user_required' USING ERRCODE = '42501';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.account_deletion_requests AS r
    WHERE r.user_id = v_user_id
  ) THEN
    RAISE EXCEPTION 'account_deletion_pending' USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
