CREATE OR REPLACE FUNCTION public.purge_chat_deletion_job(p_job_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_job public.chat_deletion_jobs%ROWTYPE; v_owner_id uuid; v_parent_deleted_at timestamptz; v_parent_found boolean:=false;
BEGIN
  IF COALESCE(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
  IF p_job_id IS NULL THEN RAISE EXCEPTION 'job_id_required' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_job FROM public.chat_deletion_jobs WHERE id=p_job_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'chat_deletion_job_not_found'; END IF;
  IF v_job.status='completed' THEN RETURN true; END IF;
  IF v_job.purge_after>clock_timestamp() THEN RAISE EXCEPTION 'chat_deletion_not_due'; END IF;
  IF v_job.resource_type='single_session' THEN
    SELECT s.user_id,s.deleted_at INTO v_owner_id,v_parent_deleted_at FROM public.chat_sessions s WHERE s.id=v_job.resource_id FOR UPDATE;
    v_parent_found:=FOUND;
  ELSIF v_job.resource_type='group' THEN
    SELECT g.owner_id,g.deleted_at INTO v_owner_id,v_parent_deleted_at FROM public.chat_groups g WHERE g.id=v_job.resource_id FOR UPDATE;
    v_parent_found:=FOUND;
  ELSE RAISE EXCEPTION 'unsupported_chat_resource_type'; END IF;
  SELECT * INTO v_job FROM public.chat_deletion_jobs WHERE id=p_job_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'chat_deletion_job_not_found'; END IF;
  IF v_job.status='completed' THEN RETURN true; END IF;
  IF v_job.status<>'processing' OR v_job.lease_until IS NULL OR v_job.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'chat_deletion_job_lease_not_owned'; END IF;
  IF v_parent_found THEN
    IF v_owner_id IS DISTINCT FROM v_job.owner_id OR v_parent_deleted_at IS DISTINCT FROM v_job.deleted_at THEN RAISE EXCEPTION 'chat_deletion_parent_mismatch'; END IF;
    PERFORM set_config('app.chat_purge_worker','on',true);
    IF v_job.resource_type='single_session' THEN
      DELETE FROM public.chat_message_versions v WHERE v.message_id IN (SELECT m.id FROM public.chat_messages m WHERE m.session_id=v_job.resource_id);
      UPDATE public.chat_messages m SET content='',deleted_at=COALESCE(m.deleted_at,v_job.deleted_at) WHERE m.session_id=v_job.resource_id;
      UPDATE public.ai_generation_records SET original_content='' WHERE session_id=v_job.resource_id AND user_id=v_job.owner_id;
      UPDATE public.encounter_session_turns SET evaluation='{}'::jsonb WHERE session_id=v_job.resource_id;
      UPDATE public.encounter_session_lifecycle SET schedule_snapshot='{}'::jsonb,settlement_result='{}'::jsonb,updated_at=clock_timestamp() WHERE session_id=v_job.resource_id;
      DELETE FROM public.encounter_session_evaluation_jobs WHERE session_id=v_job.resource_id;
      UPDATE public.encounter_turn_interaction_receipts r SET diary_id=NULL FROM public.chat_turn_charges c WHERE c.turn_id=r.turn_id AND c.session_id=v_job.resource_id AND r.diary_id IS NOT NULL;
      DELETE FROM public.encounter_diary d WHERE d.user_id=v_job.owner_id AND d.metadata->>'session_id'=v_job.resource_id::text;
      UPDATE public.story_relationship_batches SET summary=NULL,evaluation='{}'::jsonb WHERE session_id=v_job.resource_id;
      UPDATE public.story_relationship_states SET imported_memories='[]'::jsonb,updated_at=clock_timestamp() WHERE session_id=v_job.resource_id;
      DELETE FROM public.chat_memory_photos WHERE session_id=v_job.resource_id AND owner_id=v_job.owner_id;
      UPDATE public.chat_sessions SET session_data='{}'::jsonb,character_snapshot='{}'::jsonb,updated_at=clock_timestamp() WHERE id=v_job.resource_id AND user_id=v_job.owner_id;
    ELSE
      UPDATE public.chat_groups SET background_mode='none',background_memory_photo_id=NULL,name='已刪除對話',world_background='',player_name='',player_persona='',world_character_id=NULL,pinned=false,updated_at=clock_timestamp()
      WHERE id=v_job.resource_id AND owner_id=v_job.owner_id;
      DELETE FROM public.chat_group_messages WHERE group_id=v_job.resource_id;
      DELETE FROM public.chat_group_diary WHERE group_id=v_job.resource_id AND owner_id=v_job.owner_id;
      DELETE FROM public.chat_group_memory_photos WHERE group_id=v_job.resource_id AND owner_id=v_job.owner_id;
      DELETE FROM public.chat_memory_photos WHERE group_id=v_job.resource_id AND owner_id=v_job.owner_id;
      DELETE FROM public.chat_group_members WHERE group_id=v_job.resource_id;
      DELETE FROM public.chat_group_scenes WHERE group_id=v_job.resource_id;
      UPDATE public.chat_group_turns SET request_content='[purged]' WHERE group_id=v_job.resource_id;
    END IF;
  END IF;
  UPDATE public.chat_deletion_jobs SET status='completed',next_attempt_at=NULL,lease_until=NULL,last_error_code=NULL,updated_at=clock_timestamp() WHERE id=p_job_id;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_encounter_interaction(p_user_id uuid, p_character_id uuid, p_affinity_delta integer, p_event_type text, p_summary text, p_metadata jsonb DEFAULT '{}'::jsonb, p_occurred_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(affinity integer, relationship_stage text, diary_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_affinity integer;
  v_stage text;
  v_diary_id uuid;
  v_occurred_at timestamptz := COALESCE(p_occurred_at, now());
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'Trusted backend required' USING ERRCODE = '42501';
  END IF;
  IF p_user_id IS NULL OR p_character_id IS NULL THEN
    RAISE EXCEPTION 'User and character are required' USING ERRCODE = '22023';
  END IF;
  IF p_affinity_delta IS NULL OR p_affinity_delta < -10 OR p_affinity_delta > 10 THEN
    RAISE EXCEPTION 'Affinity delta must be between -10 and 10' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(char_length(btrim(p_event_type)), 0) NOT BETWEEN 1 AND 60 THEN
    RAISE EXCEPTION 'Invalid event type' USING ERRCODE = '22023';
  END IF;
  IF COALESCE(char_length(btrim(p_summary)), 0) NOT BETWEEN 1 AND 2000 THEN
    RAISE EXCEPTION 'Invalid diary summary' USING ERRCODE = '22023';
  END IF;
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata) <> 'object'
     OR pg_column_size(p_metadata) > 4000 THEN
    RAISE EXCEPTION 'Invalid diary metadata' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = p_user_id) THEN
    RAISE EXCEPTION 'User not found' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.characters c
    WHERE c.id = p_character_id AND c.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'Character not found or deleted' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.encounter_character_state AS current_state (
    user_id, character_id, affinity, relationship_stage,
    first_met_at, last_interaction_at, updated_at
  )
  VALUES (
    p_user_id, p_character_id, GREATEST(0, LEAST(100, p_affinity_delta)),
    'first_meeting', v_occurred_at, v_occurred_at, now()
  )
  ON CONFLICT (user_id, character_id) DO UPDATE
  SET affinity = GREATEST(0, LEAST(100, current_state.affinity + p_affinity_delta)),
      last_interaction_at = GREATEST(current_state.last_interaction_at, EXCLUDED.last_interaction_at),
      updated_at = now()
  RETURNING current_state.affinity INTO v_affinity;

  v_stage := CASE
    WHEN v_affinity >= 80 THEN 'special'
    WHEN v_affinity >= 50 THEN 'intimate'
    WHEN v_affinity >= 20 THEN 'close'
    WHEN v_affinity >= 1 THEN 'acquaintance'
    ELSE 'first_meeting'
  END;

  UPDATE public.encounter_character_state s
  SET relationship_stage = v_stage,
      first_met_at = COALESCE(s.first_met_at, v_occurred_at),
      updated_at = now()
  WHERE s.user_id = p_user_id AND s.character_id = p_character_id;

  INSERT INTO public.encounter_diary (
    user_id, character_id, event_type, summary, occurred_at, metadata
  )
  VALUES (
    p_user_id, p_character_id, btrim(p_event_type), btrim(p_summary), v_occurred_at, p_metadata
  )
  RETURNING id INTO v_diary_id;

  RETURN QUERY SELECT v_affinity, v_stage, v_diary_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_encounter_session_turn_evidence(p_turn_id uuid, p_session_id uuid, p_user_id uuid, p_character_id uuid, p_user_message_id uuid, p_assistant_message_id uuid, p_evaluation jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l public.encounter_session_lifecycle%ROWTYPE; c public.chat_turn_charges%ROWTYPE; um public.chat_messages%ROWTYPE; am public.chat_messages%ROWTYPE; oldrow public.encounter_session_turns%ROWTYPE; n integer;
BEGIN
  IF p_turn_id IS NULL OR p_session_id IS NULL OR p_user_id IS NULL OR p_character_id IS NULL OR p_user_message_id IS NULL OR p_assistant_message_id IS NULL OR jsonb_typeof(COALESCE(p_evaluation,'{}'::jsonb))<>'object' OR pg_column_size(COALESCE(p_evaluation,'{}'::jsonb))>8000 THEN RAISE EXCEPTION 'Invalid evidence input' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM public.chat_sessions s WHERE s.id=p_session_id AND s.user_id=p_user_id AND s.character_id=p_character_id AND s.chat_mode='encounter' AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Encounter chat is deleted or not owned' USING ERRCODE='23514'; END IF;
  SELECT * INTO l FROM public.encounter_session_lifecycle WHERE session_id=p_session_id FOR UPDATE;
  IF NOT FOUND OR l.user_id IS DISTINCT FROM p_user_id OR l.character_id IS DISTINCT FROM p_character_id OR l.status NOT IN ('active','paused','ready_to_settle') THEN RAISE EXCEPTION 'Invalid Encounter lifecycle' USING ERRCODE='23514'; END IF;
  SELECT * INTO c FROM public.chat_turn_charges WHERE turn_id=p_turn_id FOR SHARE;
  IF NOT FOUND OR c.session_id IS DISTINCT FROM p_session_id OR c.user_id IS DISTINCT FROM p_user_id OR c.status<>'settled' OR c.user_message_id IS DISTINCT FROM p_user_message_id OR c.assistant_message_id IS DISTINCT FROM p_assistant_message_id OR c.expected_assistant_message_id IS DISTINCT FROM p_assistant_message_id OR c.reserved_at IS NULL OR c.reserved_at>l.scheduled_end_at THEN RAISE EXCEPTION 'Charge evidence mismatch, unsettled, or reserved after scene end' USING ERRCODE='23514'; END IF;
  SELECT * INTO um FROM public.chat_messages WHERE id=p_user_message_id FOR SHARE;
  IF NOT FOUND OR um.session_id IS DISTINCT FROM p_session_id OR um.role<>'user' OR um.deleted_at IS NOT NULL OR length(btrim(um.content))=0 THEN RAISE EXCEPTION 'Invalid user message evidence' USING ERRCODE='23514'; END IF;
  SELECT * INTO am FROM public.chat_messages WHERE id=p_assistant_message_id FOR SHARE;
  IF NOT FOUND OR am.session_id IS DISTINCT FROM p_session_id OR am.role<>'assistant' OR am.deleted_at IS NOT NULL OR length(btrim(am.content))=0 THEN RAISE EXCEPTION 'Invalid assistant message evidence' USING ERRCODE='23514'; END IF;
  SELECT * INTO oldrow FROM public.encounter_session_turns WHERE turn_id=p_turn_id;
  IF FOUND THEN
    IF oldrow.session_id IS DISTINCT FROM p_session_id OR oldrow.user_id IS DISTINCT FROM p_user_id OR oldrow.character_id IS DISTINCT FROM p_character_id OR oldrow.user_message_id IS DISTINCT FROM p_user_message_id OR oldrow.assistant_message_id IS DISTINCT FROM p_assistant_message_id THEN RAISE EXCEPTION 'Evidence idempotency collision' USING ERRCODE='23505'; END IF;
    RETURN jsonb_build_object('turn_id',oldrow.turn_id,'turn_number',oldrow.turn_number,'status',oldrow.evaluation_status,'idempotent',true);
  END IF;
  n:=l.turn_count+1;
  INSERT INTO public.encounter_session_turns(turn_id,session_id,user_id,character_id,user_message_id,assistant_message_id,turn_number,evaluation_status,evaluation)
  VALUES(p_turn_id,p_session_id,p_user_id,p_character_id,p_user_message_id,p_assistant_message_id,n,'pending',COALESCE(p_evaluation,'{}'::jsonb));
  UPDATE public.encounter_session_lifecycle SET turn_count=n,updated_at=clock_timestamp() WHERE session_id=p_session_id;
  RETURN jsonb_build_object('turn_id',p_turn_id,'turn_number',n,'status','pending','idempotent',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.record_encounter_turn_interaction(p_turn_id uuid, p_user_id uuid, p_character_id uuid, p_affinity_delta integer, p_event_type text, p_summary text, p_metadata jsonb DEFAULT '{}'::jsonb, p_occurred_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(affinity integer, relationship_stage text, diary_id uuid, idempotent boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_inserted integer; v_affinity integer; v_stage text; v_diary_id uuid; v_receipt public.encounter_turn_interaction_receipts%ROWTYPE; v_charge public.chat_turn_charges%ROWTYPE; v_session public.chat_sessions%ROWTYPE; v_session_id uuid; v_occurred_at timestamptz:=COALESCE(p_occurred_at,now());
BEGIN
  IF COALESCE(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Trusted backend required' USING ERRCODE='42501'; END IF;
  IF p_turn_id IS NULL OR p_user_id IS NULL OR p_character_id IS NULL THEN RAISE EXCEPTION 'Turn, user and character are required' USING ERRCODE='22023'; END IF;
  IF p_affinity_delta IS NULL OR p_affinity_delta < -10 OR p_affinity_delta > 10 THEN RAISE EXCEPTION 'Affinity delta must be between -10 and 10' USING ERRCODE='22023'; END IF;
  IF COALESCE(char_length(btrim(p_event_type)),0) NOT BETWEEN 1 AND 60 OR COALESCE(char_length(btrim(p_summary)),0) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Invalid event type or diary summary' USING ERRCODE='22023'; END IF;
  IF p_metadata IS NULL OR jsonb_typeof(p_metadata)<>'object' OR pg_column_size(p_metadata)>4000 THEN RAISE EXCEPTION 'Invalid diary metadata' USING ERRCODE='22023'; END IF;
  IF NOT EXISTS(SELECT 1 FROM auth.users u WHERE u.id=p_user_id) THEN RAISE EXCEPTION 'User not found' USING ERRCODE='22023'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.characters c WHERE c.id=p_character_id AND c.deleted_at IS NULL) THEN RAISE EXCEPTION 'Character not found or deleted' USING ERRCODE='22023'; END IF;
  SELECT c.session_id INTO v_session_id FROM public.chat_turn_charges c WHERE c.turn_id=p_turn_id AND c.user_id=p_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Encounter interaction requires matching settled chat turn' USING ERRCODE='23514'; END IF;
  SELECT s.* INTO v_session FROM public.chat_sessions s WHERE s.id=v_session_id AND s.user_id=p_user_id AND s.character_id=p_character_id AND s.chat_mode='encounter' AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Encounter session ownership or lifecycle mismatch' USING ERRCODE='23514'; END IF;
  SELECT c.* INTO v_charge FROM public.chat_turn_charges c WHERE c.turn_id=p_turn_id FOR UPDATE;
  IF NOT FOUND OR v_charge.session_id IS DISTINCT FROM v_session.id OR v_charge.user_id IS DISTINCT FROM p_user_id OR v_charge.status IS DISTINCT FROM 'settled' OR v_charge.assistant_message_id IS DISTINCT FROM v_charge.expected_assistant_message_id OR p_metadata->>'session_id' IS DISTINCT FROM v_charge.session_id::text OR p_metadata->>'user_message_id' IS DISTINCT FROM v_charge.user_message_id::text OR p_metadata->>'assistant_message_id' IS DISTINCT FROM v_charge.expected_assistant_message_id::text THEN RAISE EXCEPTION 'Encounter interaction requires matching settled chat turn' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.chat_messages m WHERE m.id=v_charge.user_message_id AND m.session_id=v_charge.session_id AND m.role='user' AND m.deleted_at IS NULL AND length(btrim(m.content))>0) OR NOT EXISTS(SELECT 1 FROM public.chat_messages m WHERE m.id=v_charge.expected_assistant_message_id AND m.session_id=v_charge.session_id AND m.role='assistant' AND m.deleted_at IS NULL AND length(btrim(m.content))>0) THEN RAISE EXCEPTION 'Encounter interaction requires durable user and assistant messages' USING ERRCODE='23514'; END IF;
  INSERT INTO public.encounter_turn_interaction_receipts(turn_id,user_id,character_id) VALUES(p_turn_id,p_user_id,p_character_id) ON CONFLICT(turn_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted=ROW_COUNT;
  IF v_inserted=0 THEN
    SELECT * INTO v_receipt FROM public.encounter_turn_interaction_receipts r WHERE r.turn_id=p_turn_id FOR UPDATE;
    IF v_receipt.user_id<>p_user_id OR v_receipt.character_id<>p_character_id THEN RAISE EXCEPTION 'Turn ID reused with different owner or character' USING ERRCODE='23505'; END IF;
    IF v_receipt.diary_id IS NULL OR v_receipt.affinity IS NULL OR v_receipt.relationship_stage IS NULL THEN RAISE EXCEPTION 'Interaction receipt incomplete' USING ERRCODE='55000'; END IF;
    RETURN QUERY SELECT v_receipt.affinity,v_receipt.relationship_stage,v_receipt.diary_id,true; RETURN;
  END IF;
  INSERT INTO public.encounter_character_state AS current_state(user_id,character_id,affinity,relationship_stage,first_met_at,last_interaction_at,updated_at)
  VALUES(p_user_id,p_character_id,GREATEST(0,LEAST(100,p_affinity_delta)),'first_meeting',v_occurred_at,v_occurred_at,now())
  ON CONFLICT(user_id,character_id) DO UPDATE
  SET affinity=GREATEST(0,LEAST(100,current_state.affinity+p_affinity_delta)),last_interaction_at=GREATEST(current_state.last_interaction_at,EXCLUDED.last_interaction_at),updated_at=now()
  RETURNING current_state.affinity INTO v_affinity;
  v_stage:=CASE WHEN v_affinity>=80 THEN 'special' WHEN v_affinity>=50 THEN 'intimate' WHEN v_affinity>=20 THEN 'close' WHEN v_affinity>=1 THEN 'acquaintance' ELSE 'first_meeting' END;
  UPDATE public.encounter_character_state s SET relationship_stage=v_stage,first_met_at=COALESCE(s.first_met_at,v_occurred_at),updated_at=now() WHERE s.user_id=p_user_id AND s.character_id=p_character_id;
  INSERT INTO public.encounter_diary(user_id,character_id,event_type,summary,occurred_at,metadata) VALUES(p_user_id,p_character_id,btrim(p_event_type),btrim(p_summary),v_occurred_at,p_metadata) RETURNING id INTO v_diary_id;
  UPDATE public.encounter_turn_interaction_receipts r SET affinity=v_affinity,relationship_stage=v_stage,diary_id=v_diary_id WHERE r.turn_id=p_turn_id;
  RETURN QUERY SELECT v_affinity,v_stage,v_diary_id,false;
END;
$function$

CREATE OR REPLACE FUNCTION public.refund_chat_turn(p_user_id uuid, p_turn_id uuid, p_assistant_message_id uuid, p_failure_code text)
 RETURNS TABLE(status text, balance_silver integer, balance_diamonds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_charge public.chat_turn_charges%rowtype;
  v_wallet public.wallet_accounts%rowtype;
begin
  select c.* into v_charge
  from public.chat_turn_charges c
  where c.turn_id = p_turn_id
  for update;

  if not found or v_charge.user_id <> p_user_id then
    raise exception 'turn_not_found';
  end if;
  if v_charge.expected_assistant_message_id is distinct from p_assistant_message_id then
    raise exception 'turn_assistant_id_conflict';
  end if;

  if v_charge.status = 'refunded' then
    select w.silver_coins, w.diamonds
      into v_wallet.silver_coins, v_wallet.diamonds
    from public.wallet_accounts w
    where w.user_id = p_user_id;
    return query select 'refunded'::text, v_wallet.silver_coins, v_wallet.diamonds;
    return;
  end if;

  if v_charge.status = 'settled' then
    raise exception 'settled_turn_cannot_be_refunded';
  end if;
  if v_charge.status not in ('reserved', 'needs_reconciliation') then
    raise exception 'turn_not_refundable';
  end if;

  -- Fail closed: any row occupying the expected assistant ID blocks refund,
  -- including soft-deleted/empty rows or role/session integrity conflicts.
  if p_assistant_message_id is not null and exists (
    select 1 from public.chat_messages m where m.id = p_assistant_message_id
  ) then
    raise exception 'reply_already_persisted_or_integrity_conflict';
  end if;

  select w.* into v_wallet
  from public.wallet_accounts w
  where w.user_id = p_user_id
  for update;
  if not found then
    raise exception 'wallet_not_initialized';
  end if;

  update public.wallet_accounts w
  set silver_coins = w.silver_coins + v_charge.silver_reserved,
      diamonds = w.diamonds + v_charge.diamonds_reserved,
      updated_at = now()
  where w.user_id = p_user_id;

  if v_charge.silver_reserved > 0 then
    insert into public.wallet_transactions(user_id, currency_type, amount, biz_type, reference_id)
    values (p_user_id, 'silver_coins', v_charge.silver_reserved, 'chat_turn_refund', p_turn_id::text);
  end if;
  if v_charge.diamonds_reserved > 0 then
    insert into public.wallet_transactions(user_id, currency_type, amount, biz_type, reference_id)
    values (p_user_id, 'diamonds', v_charge.diamonds_reserved, 'chat_turn_refund', p_turn_id::text);
  end if;

  update public.chat_turn_charges c
  set status = 'refunded',
      failure_code = left(coalesce(p_failure_code, 'confirmed_failure'), 80),
      refunded_at = now(),
      updated_at = now()
  where c.turn_id = p_turn_id;

  insert into public.chat_turn_events(turn_id, user_id, event_type, stage, error_code)
  values (p_turn_id, p_user_id, 'refunded', 'recovery',
          left(coalesce(p_failure_code, 'confirmed_failure'), 80));

  select w.silver_coins, w.diamonds
    into v_wallet.silver_coins, v_wallet.diamonds
  from public.wallet_accounts w
  where w.user_id = p_user_id;

  return query select 'refunded'::text, v_wallet.silver_coins, v_wallet.diamonds;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_account_deletion()
 RETURNS TABLE(requested_at timestamp with time zone, scheduled_for timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid := auth.uid();
  v_grace_period interval;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION '請先登入';
  END IF;

  SELECT s.grace_period
    INTO v_grace_period
  FROM public.account_deletion_settings AS s
  WHERE s.singleton = true;

  IF NOT FOUND OR v_grace_period IS NULL THEN
    RAISE EXCEPTION '帳號刪除期限尚未完成環境設定，請聯絡管理員';
  END IF;

  INSERT INTO public.account_deletion_requests (user_id, scheduled_for)
  VALUES (v_user_id, pg_catalog.statement_timestamp() + v_grace_period)
  ON CONFLICT (user_id) DO NOTHING;

  RETURN QUERY
  SELECT r.requested_at, r.scheduled_for
  FROM public.account_deletion_requests AS r
  WHERE r.user_id = v_user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_chat_turn(p_user_id uuid, p_turn_id uuid, p_session_id uuid, p_user_message_id uuid, p_assistant_message_id uuid)
 RETURNS TABLE(turn_id uuid, status text, silver_reserved integer, diamonds_reserved integer, balance_silver integer, balance_diamonds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_charge public.chat_turn_charges%rowtype; v_wallet public.wallet_accounts%rowtype; v_silver integer; v_diamonds integer;
BEGIN
  IF p_user_id IS NULL OR p_turn_id IS NULL OR p_session_id IS NULL OR p_user_message_id IS NULL OR p_assistant_message_id IS NULL THEN RAISE EXCEPTION 'invalid_turn_request'; END IF;
  IF EXISTS (SELECT 1 FROM public.account_deletion_requests r WHERE r.user_id=p_user_id) THEN RAISE EXCEPTION 'account_not_active'; END IF;
  PERFORM 1 FROM public.chat_sessions s WHERE s.id=p_session_id AND s.user_id=p_user_id AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'chat_session_not_owned_or_active'; END IF;
  INSERT INTO public.chat_turn_charges(turn_id,user_id,session_id,user_message_id,expected_assistant_message_id,cost,status)
  VALUES(p_turn_id,p_user_id,p_session_id,p_user_message_id,p_assistant_message_id,2,'created')
  ON CONFLICT ON CONSTRAINT chat_turn_charges_pkey DO NOTHING;
  SELECT c.* INTO v_charge FROM public.chat_turn_charges c WHERE c.turn_id=p_turn_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'turn_not_found'; END IF;
  IF v_charge.user_id<>p_user_id OR v_charge.session_id<>p_session_id OR v_charge.user_message_id<>p_user_message_id OR v_charge.expected_assistant_message_id<>p_assistant_message_id THEN RAISE EXCEPTION 'turn_id_reuse_conflict'; END IF;
  IF v_charge.status<>'created' THEN
    SELECT w.silver_coins,w.diamonds INTO v_silver,v_diamonds FROM public.wallet_accounts w WHERE w.user_id=p_user_id;
    RETURN QUERY SELECT v_charge.turn_id,v_charge.status,v_charge.silver_reserved,v_charge.diamonds_reserved,v_silver,v_diamonds; RETURN;
  END IF;
  IF NOT EXISTS(SELECT 1 FROM public.chat_messages m WHERE m.id=p_user_message_id AND m.session_id=p_session_id AND m.role='user' AND m.deleted_at IS NULL) THEN RAISE EXCEPTION 'user_message_not_found'; END IF;
  SELECT w.* INTO v_wallet FROM public.wallet_accounts w WHERE w.user_id=p_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'wallet_not_initialized'; END IF;
  IF v_wallet.silver_coins+v_wallet.diamonds<2 THEN
    UPDATE public.chat_turn_charges c SET status='insufficient_funds',updated_at=now() WHERE c.turn_id=p_turn_id;
    INSERT INTO public.chat_turn_events(turn_id,user_id,event_type,stage,error_code) VALUES(p_turn_id,p_user_id,'insufficient_balance','reservation','insufficient_funds');
    RETURN QUERY SELECT p_turn_id,'insufficient_funds'::text,0,0,v_wallet.silver_coins,v_wallet.diamonds; RETURN;
  END IF;
  v_silver:=least(v_wallet.silver_coins,2); v_diamonds:=2-v_silver;
  UPDATE public.wallet_accounts w SET silver_coins=w.silver_coins-v_silver,diamonds=w.diamonds-v_diamonds,updated_at=now() WHERE w.user_id=p_user_id;
  IF v_silver>0 THEN INSERT INTO public.wallet_transactions(user_id,currency_type,amount,biz_type,reference_id) VALUES(p_user_id,'silver_coins',-v_silver,'chat_turn_charge',p_turn_id::text); END IF;
  IF v_diamonds>0 THEN INSERT INTO public.wallet_transactions(user_id,currency_type,amount,biz_type,reference_id) VALUES(p_user_id,'diamonds',-v_diamonds,'chat_turn_charge',p_turn_id::text); END IF;
  UPDATE public.chat_turn_charges c SET status='reserved',silver_reserved=v_silver,diamonds_reserved=v_diamonds,reserved_at=now(),updated_at=now() WHERE c.turn_id=p_turn_id;
  INSERT INTO public.chat_turn_events(turn_id,user_id,event_type,stage) VALUES(p_turn_id,p_user_id,'reserved','reservation');
  SELECT w.silver_coins,w.diamonds INTO v_silver,v_diamonds FROM public.wallet_accounts w WHERE w.user_id=p_user_id;
  RETURN QUERY SELECT p_turn_id,'reserved'::text,
    (SELECT c.silver_reserved FROM public.chat_turn_charges c WHERE c.turn_id=p_turn_id),
    (SELECT c.diamonds_reserved FROM public.chat_turn_charges c WHERE c.turn_id=p_turn_id),v_silver,v_diamonds;
END;
$function$

CREATE OR REPLACE FUNCTION public.reserve_encounter_chat_turn(p_user_id uuid, p_turn_id uuid, p_session_id uuid, p_user_message_id uuid, p_assistant_message_id uuid)
 RETURNS TABLE(turn_id uuid, status text, silver_reserved integer, diamonds_reserved integer, balance_silver integer, balance_diamonds integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l public.encounter_session_lifecycle%ROWTYPE; c public.chat_turn_charges%ROWTYPE; v_existing boolean:=false;
BEGIN
  IF p_user_id IS NULL OR p_turn_id IS NULL OR p_session_id IS NULL OR p_user_message_id IS NULL OR p_assistant_message_id IS NULL THEN RAISE EXCEPTION 'invalid_turn_request'; END IF;
  PERFORM 1 FROM public.chat_sessions s WHERE s.id=p_session_id AND s.user_id=p_user_id AND s.chat_mode='encounter' AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'encounter_chat_not_found_or_deleted' USING ERRCODE='23514'; END IF;
  SELECT * INTO l FROM public.encounter_session_lifecycle WHERE session_id=p_session_id FOR UPDATE;
  IF NOT FOUND OR l.user_id IS DISTINCT FROM p_user_id OR l.status NOT IN ('active','paused','ready_to_settle') THEN RAISE EXCEPTION 'encounter_scene_expired_or_inactive' USING ERRCODE='23514'; END IF;
  SELECT charge.* INTO c FROM public.chat_turn_charges charge WHERE charge.turn_id=p_turn_id FOR UPDATE;
  v_existing:=FOUND;
  IF v_existing THEN
    IF c.user_id IS DISTINCT FROM p_user_id OR c.session_id IS DISTINCT FROM p_session_id OR c.user_message_id IS DISTINCT FROM p_user_message_id OR c.expected_assistant_message_id IS DISTINCT FROM p_assistant_message_id THEN RAISE EXCEPTION 'turn_id_reuse_conflict' USING ERRCODE='23505'; END IF;
    IF c.status='insufficient_funds' THEN RETURN QUERY SELECT r.turn_id,r.status,r.silver_reserved,r.diamonds_reserved,r.balance_silver,r.balance_diamonds FROM public.reserve_chat_turn(p_user_id,p_turn_id,p_session_id,p_user_message_id,p_assistant_message_id) r; RETURN; END IF;
    IF c.status IN ('reserved','needs_reconciliation','settled','refunded') AND c.reserved_at IS NOT NULL AND c.reserved_at<=l.scheduled_end_at THEN
      RETURN QUERY SELECT r.turn_id,r.status,r.silver_reserved,r.diamonds_reserved,r.balance_silver,r.balance_diamonds FROM public.reserve_chat_turn(p_user_id,p_turn_id,p_session_id,p_user_message_id,p_assistant_message_id) r; RETURN;
    END IF;
  END IF;
  IF l.status<>'active' OR l.scheduled_end_at<=clock_timestamp() THEN RAISE EXCEPTION 'encounter_scene_expired_or_inactive' USING ERRCODE='23514'; END IF;
  RETURN QUERY SELECT r.turn_id,r.status,r.silver_reserved,r.diamonds_reserved,r.balance_silver,r.balance_diamonds FROM public.reserve_chat_turn(p_user_id,p_turn_id,p_session_id,p_user_message_id,p_assistant_message_id) r;
END;
$function$

