END;
$function$

CREATE OR REPLACE FUNCTION public.set_encounter_session_lifecycle_state(p_session_id uuid, p_user_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  l public.encounter_session_lifecycle%ROWTYPE;
  v_status text;
BEGIN
  IF p_session_id IS NULL OR p_user_id IS NULL
     OR p_action NOT IN ('pause','resume') THEN
    RAISE EXCEPTION 'Invalid Encounter lifecycle state request' USING ERRCODE='22023';
  END IF;

  SELECT * INTO l FROM public.encounter_session_lifecycle
  WHERE session_id=p_session_id FOR UPDATE;

  IF NOT FOUND OR l.user_id IS DISTINCT FROM p_user_id THEN
    RAISE EXCEPTION 'Encounter session not found' USING ERRCODE='P0002';
  END IF;
  IF l.character_id IS NULL THEN
    RAISE EXCEPTION 'Encounter character is unavailable' USING ERRCODE='23514';
  END IF;
  IF l.status='settled' OR l.status='cancelled'
     OR l.scheduled_end_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'Encounter scene expired or closed' USING ERRCODE='23514';
  END IF;

  IF p_action='pause' THEN
    IF l.status='paused' THEN
      RETURN jsonb_build_object('session_id',p_session_id,'status','paused','idempotent',true);
    END IF;
    IF l.status <> 'active' THEN
      RAISE EXCEPTION 'Encounter session cannot be paused from current state' USING ERRCODE='23514';
    END IF;
    v_status := 'paused';
  ELSE
    IF l.status='active' THEN
      RETURN jsonb_build_object('session_id',p_session_id,'status','active','idempotent',true);
    END IF;
    IF l.status <> 'paused' THEN
      RAISE EXCEPTION 'Encounter session cannot be resumed from current state' USING ERRCODE='23514';
    END IF;
    v_status := 'active';
  END IF;

  UPDATE public.encounter_session_lifecycle
  SET status=v_status,updated_at=clock_timestamp()
  WHERE session_id=p_session_id;

  RETURN jsonb_build_object('session_id',p_session_id,'status',v_status,'idempotent',false);
END;
$function$

CREATE OR REPLACE FUNCTION public.settle_chat_turn(p_user_id uuid, p_turn_id uuid, p_assistant_message_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_charge public.chat_turn_charges%rowtype;
begin
  select c.* into v_charge from public.chat_turn_charges c where c.turn_id=p_turn_id for update;
  if not found or v_charge.user_id <> p_user_id then raise exception 'turn_not_found'; end if;
  if v_charge.expected_assistant_message_id is distinct from p_assistant_message_id then raise exception 'turn_assistant_id_conflict'; end if;
  if v_charge.status = 'settled' then
    if v_charge.assistant_message_id is distinct from p_assistant_message_id then raise exception 'settled_turn_reply_id_conflict'; end if;
    return 'settled';
  end if;
  if v_charge.status not in ('reserved','needs_reconciliation') then raise exception 'turn_not_settleable'; end if;
  if not exists (select 1 from public.chat_messages m where m.id=p_assistant_message_id and m.session_id=v_charge.session_id and m.role='assistant' and m.deleted_at is null and length(btrim(m.content)) > 0) then
    raise exception 'durable_assistant_reply_not_found';
  end if;
  update public.chat_turn_charges c set status='settled', assistant_message_id=p_assistant_message_id, settled_at=now(), updated_at=now() where c.turn_id=p_turn_id;
  insert into public.chat_turn_events(turn_id,user_id,event_type,stage) values (p_turn_id,p_user_id,'settled','persistence');
  return 'settled';
end;
$function$

CREATE OR REPLACE FUNCTION public.settle_encounter_session(p_session_id uuid, p_affinity_delta integer, p_relationship_stage text, p_memories jsonb DEFAULT '[]'::jsonb, p_evaluation jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  l public.encounter_session_lifecycle%ROWTYPE;
  v_current integer := 0;
  v_final integer := 0;
  v_state_id uuid;
  v_result jsonb;
BEGIN
  IF p_session_id IS NULL OR p_affinity_delta IS NULL
     OR p_affinity_delta NOT BETWEEN -100 AND 100
     OR p_relationship_stage NOT IN ('hostile','dislike','wary','first_meeting','acquaintance','close','intimate','special')
     OR jsonb_typeof(COALESCE(p_memories,'[]'::jsonb)) <> 'array'
     OR pg_column_size(COALESCE(p_memories,'[]'::jsonb)) > 20000
     OR jsonb_typeof(COALESCE(p_evaluation,'{}'::jsonb)) <> 'object'
     OR pg_column_size(COALESCE(p_evaluation,'{}'::jsonb)) > 12000 THEN
    RAISE EXCEPTION 'Invalid Encounter settlement payload' USING ERRCODE='22023';
  END IF;

  SELECT * INTO l FROM public.encounter_session_lifecycle
  WHERE session_id=p_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Encounter lifecycle not found' USING ERRCODE='P0002'; END IF;
  IF l.status='settled' THEN
    RETURN jsonb_build_object('settled',true,'idempotent',true,'result',l.settlement_result);
  END IF;
  IF l.character_id IS NULL THEN
    RAISE EXCEPTION 'Encounter character is no longer available for relationship settlement' USING ERRCODE='23514';
  END IF;
  IF l.status NOT IN ('active','paused','ready_to_settle')
     OR l.scheduled_end_at > clock_timestamp() THEN
    RAISE EXCEPTION 'Encounter scene has not reached scheduled end or is not settleable' USING ERRCODE='23514';
  END IF;

  -- A turn reserved before expiry may still be generating/persisting its reply.
  -- Do not settle until every such reservation is settled or refunded.
  IF EXISTS (
    SELECT 1 FROM public.chat_turn_charges c
    WHERE c.session_id=p_session_id
      AND c.reserved_at IS NOT NULL
      AND c.reserved_at <= l.scheduled_end_at
      AND c.status IN ('reserved','needs_reconciliation')
  ) THEN
    RAISE EXCEPTION 'Encounter has pending pre-expiry turns' USING ERRCODE='23514';
  END IF;

  IF (SELECT count(*) FROM public.encounter_session_turns t WHERE t.session_id=p_session_id) <> l.turn_count THEN
    RAISE EXCEPTION 'Encounter turn evidence is incomplete' USING ERRCODE='23514';
  END IF;

  INSERT INTO public.encounter_character_state(user_id,character_id,affinity,relationship_stage,first_met_at,last_interaction_at)
  VALUES(l.user_id,l.character_id,0,'first_meeting',clock_timestamp(),clock_timestamp())
  ON CONFLICT (user_id,character_id) DO NOTHING;
  SELECT s.id,s.affinity INTO v_state_id,v_current
  FROM public.encounter_character_state s
  WHERE s.user_id=l.user_id AND s.character_id=l.character_id FOR UPDATE;

  v_final := greatest(-100,least(100,v_current+p_affinity_delta));
  UPDATE public.encounter_character_state
  SET affinity=v_final,relationship_stage=p_relationship_stage,
      last_interaction_at=clock_timestamp(),updated_at=clock_timestamp()
  WHERE id=v_state_id;

  v_result := jsonb_build_object(
    'final_affinity',v_final,'affinity_delta',v_final-v_current,
    'relationship_stage',p_relationship_stage,'memories',COALESCE(p_memories,'[]'::jsonb),
    'evaluation',COALESCE(p_evaluation,'{}'::jsonb),'turn_count',l.turn_count,
    'source_session_id',p_session_id
  );
  UPDATE public.encounter_session_lifecycle
  SET status='settled',settlement_delta=v_final-v_current,
      settlement_result=v_result,settled_at=clock_timestamp(),updated_at=clock_timestamp()
  WHERE session_id=p_session_id;
  RETURN jsonb_build_object('settled',true,'idempotent',false,'result',v_result);
END;
$function$

CREATE OR REPLACE FUNCTION public.soft_delete_character(p_character_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_author_id uuid;
  v_first_published_at timestamptz;
  v_deleted_at timestamptz;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
  END IF;
  IF NOT public.account_is_active() THEN
    RAISE EXCEPTION 'account_deletion_pending' USING ERRCODE = '42501';
  END IF;

  SELECT c.author_id, c.first_published_at, c.deleted_at
    INTO v_author_id, v_first_published_at, v_deleted_at
  FROM public.characters c
  WHERE c.id = p_character_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Character not found.';
  END IF;
  IF v_author_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Not allowed to delete this character.' USING ERRCODE = '42501';
  END IF;
  IF v_deleted_at IS NOT NULL THEN
    RETURN v_deleted_at;
  END IF;

  v_deleted_at := now();

  UPDATE public.characters
  SET visibility = 'private',
      review_status = 'draft',
      deleted_at = v_deleted_at,
      deletion_reason = 'author_deleted'
  WHERE id = p_character_id;

  UPDATE public.character_stories
  SET visibility = 'private'
  WHERE character_id = p_character_id;

  UPDATE public.chat_sessions cs
  SET character_snapshot = COALESCE(cs.character_snapshot, '{}'::jsonb) ||
    jsonb_build_object(
      'authorId', v_author_id,
      'visibility', 'private',
      'firstPublishedAt', v_first_published_at,
      'deletedAt', v_deleted_at
    ),
    updated_at = now()
  WHERE cs.character_id = p_character_id;

  UPDATE public.chat_group_members gm
  SET character_snapshot = COALESCE(gm.character_snapshot, '{}'::jsonb) ||
    jsonb_build_object(
      'authorId', v_author_id,
      'visibility', 'private',
      'firstPublishedAt', v_first_published_at,
      'deletedAt', v_deleted_at
    )
  WHERE gm.character_id = p_character_id;

  UPDATE public.chat_group_messages gm
  SET speaker_snapshot = COALESCE(gm.speaker_snapshot, '{}'::jsonb) ||
    jsonb_build_object(
      'authorId', v_author_id,
      'visibility', 'private',
      'firstPublishedAt', v_first_published_at,
      'deletedAt', v_deleted_at
    )
  WHERE gm.character_id = p_character_id;

  RETURN v_deleted_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_author_follower_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'INSERT' then
    update public.profiles
       set follower_count = follower_count + 1
     where id = new.author_id;
    return new;
  elsif tg_op = 'DELETE' then
    update public.profiles
       set follower_count = greatest(follower_count - 1, 0)
     where id = old.author_id;
    return old;
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_character_chat_snapshot(p_character_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_author_id uuid;
  v_visibility text;
  v_first_published_at timestamptz;
  v_deleted_at timestamptz;
  v_count integer := 0;
  v_rows integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501';
  END IF;
  IF NOT public.account_is_active() THEN
    RAISE EXCEPTION 'account_deletion_pending' USING ERRCODE = '42501';
  END IF;

  SELECT c.author_id, c.visibility, c.first_published_at, c.deleted_at
    INTO v_author_id, v_visibility, v_first_published_at, v_deleted_at
  FROM public.characters c
  WHERE c.id = p_character_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Character not found.';
  END IF;
  IF v_author_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Not allowed to update this character snapshot.' USING ERRCODE = '42501';
  END IF;

  UPDATE public.chat_sessions cs
  SET character_snapshot = COALESCE(cs.character_snapshot, '{}'::jsonb) ||
    jsonb_build_object(
      'authorId', v_author_id,
      'visibility', v_visibility,
      'firstPublishedAt', v_first_published_at,
      'deletedAt', v_deleted_at
    ),
    updated_at = now()
  WHERE cs.character_id = p_character_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_count := v_count + v_rows;

  UPDATE public.chat_group_members gm
  SET character_snapshot = COALESCE(gm.character_snapshot, '{}'::jsonb) ||
    jsonb_build_object(
      'authorId', v_author_id,
      'visibility', v_visibility,
      'firstPublishedAt', v_first_published_at,
      'deletedAt', v_deleted_at
    )
  WHERE gm.character_id = p_character_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_count := v_count + v_rows;

  UPDATE public.chat_group_messages gm
  SET speaker_snapshot = COALESCE(gm.speaker_snapshot, '{}'::jsonb) ||
    jsonb_build_object(
      'authorId', v_author_id,
      'visibility', v_visibility,
      'firstPublishedAt', v_first_published_at,
      'deletedAt', v_deleted_at
    )
  WHERE gm.character_id = p_character_id;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  v_count := v_count + v_rows;

  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.test_grant_diamonds_200()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_balance integer;
begin
  if v_user_id is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.account_deletion_requests adr
    where adr.user_id = v_user_id
  ) then
    raise exception 'account deletion pending' using errcode = '42501';
  end if;

  select wa.diamonds
    into v_balance
  from public.wallet_accounts wa
  where wa.user_id = v_user_id
  for update;

  if not found then
    raise exception 'wallet account not found' using errcode = 'P0002';
  end if;

  if exists (
    select 1
    from public.wallet_transactions wt
    where wt.user_id = v_user_id
      and wt.currency_type = 'diamonds'
      and wt.biz_type = 'test_purchase_200'
      and wt.reference_id = 'test_purchase_200_once'
  ) then
    return jsonb_build_object('diamonds', v_balance, 'granted', false);
  end if;

  update public.wallet_accounts
    set diamonds = diamonds + 200,
        updated_at = now()
  where user_id = v_user_id
  returning diamonds into v_balance;

  insert into public.wallet_transactions
    (user_id, currency_type, amount, biz_type, reference_id)
  values
    (v_user_id, 'diamonds', 200, 'test_purchase_200', 'test_purchase_200_once');

  return jsonb_build_object('diamonds', v_balance, 'granted', true);
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_affinity_session_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid;
  v_character_id uuid;
  v_chat_mode text;
BEGIN
  SELECT s.user_id, s.character_id, s.chat_mode
    INTO v_user_id, v_character_id, v_chat_mode
  FROM public.chat_sessions AS s
  WHERE s.id = NEW.session_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Affinity session does not exist' USING ERRCODE = '23503';
  END IF;

  IF v_user_id IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'Affinity session owner mismatch' USING ERRCODE = '23514';
  END IF;

  IF NEW.character_id IS NOT NULL
     AND v_character_id IS DISTINCT FROM NEW.character_id THEN
    RAISE EXCEPTION 'Affinity session character mismatch' USING ERRCODE = '23514';
  END IF;

  IF TG_TABLE_NAME = 'encounter_session_lifecycle'
     AND v_chat_mode <> 'encounter' THEN
    RAISE EXCEPTION 'Encounter lifecycle requires an Encounter session' USING ERRCODE = '23514';
  ELSIF TG_TABLE_NAME = 'story_relationship_states'
     AND v_chat_mode <> 'story' THEN
    RAISE EXCEPTION 'Story relationship requires a Story session' USING ERRCODE = '23514';
  ELSIF TG_TABLE_NAME = 'story_relationship_batches'
     AND v_chat_mode <> 'story' THEN
    RAISE EXCEPTION 'Story batch requires a Story session' USING ERRCODE = '23514';
  ELSIF TG_TABLE_NAME = 'encounter_session_turns'
     AND v_chat_mode <> 'encounter' THEN
    RAISE EXCEPTION 'Encounter turn requires an Encounter session' USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_chat_group_background_photo()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.background_mode NOT IN ('avatar','none','memory') THEN
    RAISE EXCEPTION 'invalid_group_background_mode';
  END IF;

  IF NEW.background_mode = 'memory' THEN
    IF NEW.background_memory_photo_id IS NULL OR NOT EXISTS (
      SELECT 1
      FROM public.chat_memory_photos AS photo
      WHERE photo.id = NEW.background_memory_photo_id
        AND photo.chat_type = 'group'
        AND photo.group_id = NEW.id
        AND photo.owner_id = NEW.owner_id
        AND photo.status = 'active'
        AND photo.deleted_at IS NULL
        AND photo.expires_at > pg_catalog.now()
    ) THEN
      RAISE EXCEPTION 'group_background_photo_not_owned_or_active';
    END IF;
  ELSE
    NEW.background_memory_photo_id := NULL;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_encounter_evaluation_job_link()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_user_id uuid;
  v_character_id uuid;
  v_chat_mode text;
BEGIN
  SELECT s.user_id,s.character_id,s.chat_mode
  INTO v_user_id,v_character_id,v_chat_mode
  FROM public.chat_sessions AS s
  WHERE s.id=NEW.session_id;

  IF NOT FOUND OR v_user_id IS DISTINCT FROM NEW.user_id
     OR v_chat_mode <> 'encounter'
     OR (NEW.character_id IS NOT NULL AND v_character_id IS DISTINCT FROM NEW.character_id) THEN
    RAISE EXCEPTION 'Encounter evaluation job session link is invalid' USING ERRCODE='23514';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_encounter_turn_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_user_message_session uuid; v_user_message_role text; v_assistant_message_session uuid; v_assistant_message_role text; v_charge_session uuid; v_charge_user uuid;
BEGIN
  PERFORM 1 FROM public.chat_sessions s WHERE s.id=NEW.session_id AND s.user_id=NEW.user_id AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Encounter evidence parent session is deleted or inaccessible' USING ERRCODE='23514'; END IF;
  SELECT m.session_id,m.role INTO v_user_message_session,v_user_message_role FROM public.chat_messages m WHERE m.id=NEW.user_message_id;
  SELECT m.session_id,m.role INTO v_assistant_message_session,v_assistant_message_role FROM public.chat_messages m WHERE m.id=NEW.assistant_message_id;
  SELECT c.session_id,c.user_id INTO v_charge_session,v_charge_user FROM public.chat_turn_charges c WHERE c.turn_id=NEW.turn_id;
  IF v_user_message_session IS DISTINCT FROM NEW.session_id OR v_user_message_role<>'user' THEN RAISE EXCEPTION 'Encounter user message does not belong to the session' USING ERRCODE='23514'; END IF;
  IF v_assistant_message_session IS DISTINCT FROM NEW.session_id OR v_assistant_message_role<>'assistant' THEN RAISE EXCEPTION 'Encounter assistant message does not belong to the session' USING ERRCODE='23514'; END IF;
  IF v_charge_session IS DISTINCT FROM NEW.session_id OR v_charge_user IS DISTINCT FROM NEW.user_id THEN RAISE EXCEPTION 'Encounter turn charge does not match session owner' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_story_relationship_batch_sources()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_expected_count integer; v_distinct_count integer; v_valid_count integer;
BEGIN
  PERFORM 1 FROM public.chat_sessions s WHERE s.id=NEW.session_id AND s.user_id=NEW.user_id AND s.chat_mode='story' AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Story session is deleted or inaccessible' USING ERRCODE='23514'; END IF;
  v_expected_count:=NEW.last_turn_number-NEW.first_turn_number+1;
  IF NEW.first_turn_number<1 OR NEW.last_turn_number<NEW.first_turn_number OR v_expected_count NOT BETWEEN 1 AND 5 OR cardinality(NEW.source_turn_ids)<>v_expected_count THEN RAISE EXCEPTION 'Story batch turn range does not match source turn count' USING ERRCODE='23514'; END IF;
  SELECT count(DISTINCT source_id) INTO v_distinct_count FROM unnest(NEW.source_turn_ids) AS source(source_id);
  IF v_distinct_count<>cardinality(NEW.source_turn_ids) THEN RAISE EXCEPTION 'Story batch source turn IDs must be unique' USING ERRCODE='23514'; END IF;
  SELECT count(*) INTO v_valid_count FROM unnest(NEW.source_turn_ids) AS source(source_id) JOIN public.chat_turn_charges charge ON charge.turn_id=source.source_id WHERE charge.session_id=NEW.session_id AND charge.user_id=NEW.user_id AND charge.status='settled';
  IF v_valid_count<>cardinality(NEW.source_turn_ids) THEN RAISE EXCEPTION 'Story batch sources must be settled turns from the same session and owner' USING ERRCODE='23514'; END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_story_relationship_origin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_source_user uuid; v_source_character uuid; v_source_status text;
BEGIN
  PERFORM 1 FROM public.chat_sessions s WHERE s.id=NEW.session_id AND s.user_id=NEW.user_id AND s.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Story session is deleted or inaccessible' USING ERRCODE='23514'; END IF;
  IF NEW.origin_mode='encounter_snapshot' AND NEW.source_encounter_session_id IS NOT NULL THEN
    PERFORM 1 FROM public.chat_sessions s WHERE s.id=NEW.source_encounter_session_id AND s.user_id=NEW.user_id AND s.deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Encounter snapshot source session is deleted' USING ERRCODE='23514'; END IF;
    SELECT l.user_id,l.character_id,l.status INTO v_source_user,v_source_character,v_source_status FROM public.encounter_session_lifecycle l WHERE l.session_id=NEW.source_encounter_session_id;
    IF NOT FOUND OR v_source_user IS DISTINCT FROM NEW.user_id OR (NEW.character_id IS NOT NULL AND v_source_character IS DISTINCT FROM NEW.character_id) OR v_source_status<>'settled' THEN RAISE EXCEPTION 'Encounter snapshot source is invalid or not settled' USING ERRCODE='23514'; END IF;
  ELSIF NEW.origin_mode='encounter_snapshot' AND (TG_OP='INSERT' OR OLD.source_encounter_session_id IS NULL) THEN
    RAISE EXCEPTION 'Encounter snapshot source is required at creation' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END;
$function$
